int calculateMinimumHP(vector<vector<int>>& dungeon) {
    int m = dungeon.size(), n = dungeon[0].size();
    vector<int> dp(n);

    for (int i = m - 1; i >= 0; i--) {
        for (int j = n - 1; j >= 0; j--) {
            if(i == m-1 && j == n-1){
                dp[j] = min(0, dungeon[i][j]);
            }
            else if (i == m - 1) {
                dp[j] = min(0, dp[j + 1] + dungeon[i][j]);
            }
            else if (j == n - 1) {
                dp[j] = min(0, dp[j] + dungeon[i][j]);
            }
            else {
                dp[j] = min(0, max(dp[j], dp[j + 1]) + dungeon[i][j]);
            }
        }
    }

    return abs(dp[0]) + 1;
}
``` 

