    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::function<bool(const std::pair<int, int>&, const std::pair<int, int>&)>> min_heap(
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return nums1[a.first] + nums2[a.second] > nums1[b.first] + nums2[b.second];
        }
    );

    // Initialize the priority queue with the first element of each vector
    for (int i = 0; i < nums1.size(); ++i) {
