    std::vector<int> res(nums2.size());
    for (int i = 0; i < nums2.size(); ++i) {
        auto it = s.upper_bound(nums2[i]);
        if (it == s.end()) it = s.begin();
        res[i] = *it;
        s.erase(it);
    }
    return res;
}
