    Arrays.sort(nums);
    int i = 0, j = nums.length - 1;
    while (i < j) {
        int sum = nums[i] + nums[j];
        if (sum < k && sum > maxSum) {
            maxSum = sum;
        }
        if (sum <= k) {
            i++;
        } else {
            j--;
        }
    }
    return maxSum;
}
